Fixed 'The tile texture was not found in the tilemap tileset' error as well. It signifies failure of rendering of shadows on a map. My project have custom shadows, so I didn't see problems.
Attaching modified
www/js/libs/rpgmaker.js
file (for pixi v6). Download and replace to fix shadows rendering.
Or apply this diff (diff will work on rpgmaker.js for pixi v7 as well):
Git:
Index: www/js/libs/rpgmaker.js
IDEA additional info:
Subsystem: com.intellij.openapi.diff.impl.patch.CharsetEP
<+>UTF-8
===================================================================
diff --git a/www/js/libs/rpgmaker.js b/www/js/libs/rpgmaker.js
--- a/www/js/libs/rpgmaker.js    (revision Staged)
+++ b/www/js/libs/rpgmaker.js    (date 1749214480608)
@@ -1426,6 +1426,59 @@
         }
     };

+    const tile = PIXI.tilemap.RectTileLayer.prototype.tile;
+    PIXI.tilemap.RectTileLayer.prototype.tile = function (
+        tileTexture,
+        x,
+        y,
+        options = {}
+    ) {
+        if (tileTexture !== -1) {
+            tile.call(this, tileTexture, x, y, options);
+            return;
+        }
+
+        const {
+            u = 0,
+            v = 0,
+            tileWidth = 0,
+            tileHeight = 0,
+            animX = 0,
+            animY = 0,
+            rotate = 0,
+            animCountX = 1024,
+            animCountY = 1024,
+            animDivisor = 1,
+            alpha = 1,
+        } = options;
+
+        if (!(tileWidth > 0 && tileHeight > 0)) {
+            console.error(`Invalid shadow size (${tileWidth}x${tileHeight})`);
+            return;
+        }
+
+        const pb = this.pointsBuf;
+
+        this.hasAnimatedTile = this.hasAnimatedTile || animX > 0 || animY > 0;
+
+        pb.push(u ?? 0);
+        pb.push(v ?? 0);
+        pb.push(x);
+        pb.push(y);
+        pb.push(tileWidth);
+        pb.push(tileHeight);
+        pb.push(rotate);
+        pb.push(animX | 0);
+        pb.push(animY | 0);
+        pb.push(tileTexture);
+        pb.push(animCountX);
+        pb.push(animCountY);
+        pb.push(animDivisor);
+        pb.push(alpha);
+
+        this.tilemapBounds.addFramePad(x, y, x + tileWidth, y + tileHeight, 0, 0);
+    }
+
     function LevelLoader() {
         this.initialize.apply(this, arguments);
     }
